<?php

declare(strict_types=1);

/**
 * Creates four idempotent YOOtheme Builder catalogue demos from the products
 * generated by tools/seed-large-demo-catalog.php.
 *
 * Run from the host repository root:
 *   docker compose exec -T app php /dev/stdin < tools/seed-catalog-mode-demos.php
 */
final class CatalogModeDemoSeeder
{
    private const ARTICLE_CATEGORY_ID = 2;
    private const CREATED_BY = 42;

    private PDO $db;
    private string $now;
    private array $products = [];

    public function __construct()
    {
        $host = getenv('JOOMLA_DB_HOST') ?: 'db';
        $name = getenv('JOOMLA_DB_NAME') ?: 'database';
        $user = getenv('JOOMLA_DB_USER') ?: 'joomla';
        $pass = getenv('JOOMLA_DB_PASSWORD') ?: '';

        $this->db = new PDO(
            "mysql:host={$host};dbname={$name};charset=utf8mb4",
            $user,
            $pass,
            [
                PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
                PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
                PDO::ATTR_EMULATE_PREPARES => false,
            ]
        );
        $this->now = gmdate('Y-m-d H:i:s');
    }

    public function run(): void
    {
        $this->products = $this->loadProducts();
        if (count($this->products) < 8) {
            throw new RuntimeException(
                'The large demo catalogue is missing. Run tools/seed-large-demo-catalog.php first.'
            );
        }

        $pages = [
            'ytdynamics-catalog-layouts' => [
                'title' => 'Каталоги на элементах YTDynamics',
                'menu' => 'CATALOG LAYOUTS',
                'layout' => $this->landingLayout(),
            ],
            'ytdynamics-catalog-tile' => [
                'title' => 'Каталог · крупная плитка',
                'menu' => 'CATALOG TILE',
                'layout' => $this->modeLayout(
                    'Крупная плитка',
                    'Карточка с постоянной областью и независимой панелью вариантов, покупки и быстрого просмотра.',
                    $this->tileCatalogue()
                ),
            ],
            'ytdynamics-catalog-compact' => [
                'title' => 'Каталог · компактная плитка',
                'menu' => 'CATALOG COMPACT',
                'layout' => $this->modeLayout(
                    'Компактная плитка',
                    'Плотная витрина: до пяти карточек в строке, короткий набор данных и постоянные действия.',
                    $this->compactCatalogue()
                ),
            ],
            'ytdynamics-catalog-list' => [
                'title' => 'Каталог · строки',
                'menu' => 'CATALOG LIST',
                'layout' => $this->modeLayout(
                    'Строчное представление',
                    'Изображение, описание, характеристики, варианты и покупка собраны стандартными колонками Builder.',
                    $this->listCatalogue()
                ),
            ],
            'ytdynamics-catalog-price' => [
                'title' => 'Каталог · прайс',
                'menu' => 'CATALOG PRICE',
                'layout' => $this->modeLayout(
                    'Прайс-таблица',
                    'Семантическая RM Table с вложенными товарными элементами и карточками на мобильном.',
                    $this->priceCatalogue()
                ),
            ],
        ];

        $result = [];
        $this->db->beginTransaction();
        try {
            foreach ($pages as $alias => $page) {
                $articleId = $this->upsertArticle($alias, $page['title'], $page['layout']);
                $this->upsertMenu($alias, $page['menu'], $articleId);
                $result[$alias] = '/index.php/' . $alias;
            }
            $this->db->commit();
        } catch (Throwable $error) {
            $this->db->rollBack();
            throw $error;
        }

        echo json_encode(
            ['status' => 'ok', 'products' => count($this->products), 'pages' => $result],
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR
        ) . PHP_EOL;
    }

    private function loadProducts(): array
    {
        $sql = <<<'SQL'
SELECT p.id,
       p.title,
       p.alias,
       p.code,
       p.meta_variability,
       c.title AS category_title
FROM joom_radicalmart_products AS p
INNER JOIN (
    SELECT meta_variability, MIN(id) AS product_id
    FROM joom_radicalmart_products
    WHERE alias LIKE 'mega-demo-%' AND meta_variability > 0 AND state = 1
    GROUP BY meta_variability
) AS selected ON selected.product_id = p.id
LEFT JOIN joom_radicalmart_categories AS c ON c.id = p.category
ORDER BY c.id, p.id
LIMIT 12
SQL;

        return $this->query($sql)->fetchAll();
    }

    private function landingLayout(): array
    {
        $modes = [
            ['Крупная плитка', 'Изображение, цена и наличие постоянно; варианты и действия появляются отдельной панелью.', 'ytdynamics-catalog-tile', 'grid'],
            ['Компактная плитка', 'Плотная сетка без скрытой области — подходит для быстрого просмотра большого ассортимента.', 'ytdynamics-catalog-compact', 'thumbnails'],
            ['Строки', 'Три независимые зоны: изображение, информация и управление товаром.', 'ytdynamics-catalog-list', 'list'],
            ['Прайс', 'Табличная плотность на десктопе и карточки с подписями ячеек на мобильном.', 'ytdynamics-catalog-price', 'table'],
        ];

        $cards = [];
        foreach ($modes as [$title, $description, $alias, $icon]) {
            $cards[] = $this->node('rmgrid_item', [
                'panel_style' => 'card-default',
                'panel_padding' => 'default',
                'name' => $title,
            ], [
                $this->node('icon', ['icon' => $icon, 'icon_width' => 48, 'icon_color' => 'primary']),
                $this->node('headline', [
                    'content' => $title,
                    'title_element' => 'h2',
                    'title_style' => 'h3',
                    'margin_top' => 'small',
                ]),
                $this->node('text', ['content' => $description, 'margin_top' => 'small']),
                $this->button('Открыть стенд', '/index.php/' . $alias, 'primary'),
            ]);
        }

        // The same four compositions are also mounted on one page and gated
        // by ProductListState. RM Toolbar changes the persisted layout and a
        // reload renders only the selected Builder tree, matching a real
        // category page without shipping four hidden catalogues to the DOM.
        $tile = $this->tileCatalogue();
        $tile[0]['props']['mode'] = 'radicalmart_tile';
        $compact = $this->compactCatalogue();
        $compact[0]['props']['mode'] = 'radicalmart_compact';
        $list = $this->listCatalogue();
        $list[0]['props']['mode'] = 'radicalmart_list';
        $price = $this->priceCatalogue();
        $price[0]['props']['mode'] = 'radicalmart_price';

        return $this->layout([
            $this->hero(
                'Четыре каталога из одних и тех же элементов',
                'Каждое представление — самостоятельная Builder-композиция. В карточках нет зашитой раскладки.'
            ),
            $this->section('Выберите представление', [
                $this->node('rmgrid', [
                    'mode' => 'default',
                    'grid_column_gap' => 'medium',
                    'grid_row_gap' => 'medium',
                    'grid_default' => '1',
                    'grid_small' => '2',
                    'grid_large' => '4',
                ], $cards),
            ]),
            $this->section('Интерактивный каталог', array_merge([
                $this->node('rmordering', [
                    'ordering_width' => 'medium',
                    'margin_bottom' => 'small',
                ]),
                $this->node('rmlayoutswitcher', [
                    'show_grid_button' => true,
                    'show_compact_button' => true,
                    'show_list_button' => true,
                    'show_table_button' => true,
                    'switcher_style' => 'icon_text',
                    'switcher_breakpoint' => 's',
                    'margin_bottom' => 'large',
                ]),
            ], $tile, $compact, $list, $price), 'muted', 'default'),
        ]);
    }

    private function modeLayout(string $title, string $description, array $catalogue): array
    {
        return $this->layout([
            $this->hero($title, $description),
            $this->section('', array_merge([$this->modeNavigation()], $catalogue), 'muted', 'default'),
        ]);
    }

    private function tileCatalogue(): array
    {
        $cards = [];
        foreach ($this->products as $product) {
            $cards[] = $this->node('rmgrid_item', [
                'panel_style' => 'card-default',
                'panel_padding' => 'default',
                'name' => $product['title'],
            ], [$this->productCard((int) $product['id'], (string) $product['category_title'], 'tile')]);
        }

        return [$this->node('rmgrid', [
            'mode' => 'default',
            'grid_column_gap' => 'medium',
            'grid_row_gap' => 'medium',
            'grid_default' => '1',
            'grid_small' => '2',
            'grid_large' => '3',
            'filter' => false,
        ], $cards)];
    }

    private function compactCatalogue(): array
    {
        $cards = [];
        foreach ($this->products as $product) {
            $id = (int) $product['id'];
            $cards[] = $this->node('rmgrid_item', [
                'panel_style' => 'card-default',
                'panel_padding' => 'small',
                'name' => $product['title'],
            ], [
                $this->node('rmproductcard', ['product_id' => $id], [
                    $this->node('rmproductcard_main', [], [
                        $this->node('rmproductfield', [
                            'product_id' => $id,
                            'field' => 'image',
                            'link_product' => true,
                            'image_ratio' => '4/3',
                            'image_fit' => 'contain',
                            'image_loading' => 'lazy',
                        ]),
                        $this->node('text', [
                            'content' => $product['category_title'],
                            'text_style' => 'meta',
                            'margin_top' => 'small',
                        ]),
                        $this->node('rmproductfield', [
                            'product_id' => $id,
                            'field' => 'title',
                            'link_product' => true,
                            'title_element' => 'h3',
                            'title_style' => 'h5',
                            'margin_top' => 'small',
                        ]),
                        $this->node('rmproductfield', [
                            'product_id' => $id,
                            'field' => 'price',
                            'text_style' => 'lead',
                            'show_base_price' => true,
                            'show_discount' => true,
                            'margin_top' => 'small',
                        ]),
                        $this->node('rmproductfield', [
                            'product_id' => $id,
                            'field' => 'availability',
                            'text_style' => 'small',
                            'margin_top' => 'small',
                        ]),
                        $this->node('rmbuy', [
                            'product_id' => $id,
                            'label' => 'В корзину',
                            'button_style' => 'primary',
                            'button_size' => 'small',
                            'show_count' => false,
                            'fullwidth' => true,
                            'margin_top' => 'small',
                        ]),
                        $this->node('rmquickview', [
                            'product_id' => $id,
                            'label' => 'Быстрый просмотр',
                            'button_style' => 'text',
                            'button_size' => 'small',
                            'modal_size' => 'container',
                            'fullwidth' => true,
                            'margin_top' => 'small',
                        ]),
                    ]),
                ]),
            ]);
        }

        return [$this->node('rmgrid', [
            'mode' => 'default',
            'grid_column_gap' => 'small',
            'grid_row_gap' => 'small',
            'grid_default' => '2',
            'grid_small' => '3',
            'grid_medium' => '4',
            'grid_large' => '5',
            'filter' => false,
        ], $cards)];
    }

