    private function priceCatalogue(): array
    {
        $header = $this->node('rmtable_item', ['row_type' => 'head', 'name' => 'Заголовок'], [
            $this->tableCell('Товар', 'Товар', ['cell_type' => 'header', 'scope' => 'col', 'cell_width' => 'expand']),
            $this->tableCell('Артикул', 'Артикул', ['cell_type' => 'header', 'scope' => 'col', 'cell_width' => 'small']),
            $this->tableCell('Цена', 'Цена', ['cell_type' => 'header', 'scope' => 'col', 'cell_width' => 'small']),
            $this->tableCell('Наличие', 'Наличие', ['cell_type' => 'header', 'scope' => 'col', 'cell_width' => 'small']),
            $this->tableCell('Действие', 'Действие', ['cell_type' => 'header', 'scope' => 'col', 'cell_width' => 'medium']),
        ]);

        $rows = [$header];
        foreach ($this->products as $product) {
            $id = (int) $product['id'];
            $rows[] = $this->node('rmtable_item', [
                'row_type' => 'body',
                'row_aria_label' => $product['title'],
                'name' => $product['title'],
            ], [
                $this->tableCell('', 'Товар', [
                    'cell_type' => 'header',
                    'scope' => 'row',
                    'mobile_behavior' => 'full',
                    'mobile_label_position' => 'hidden',
                ], [
                    $this->row([
                        $this->column([
                            $this->node('rmproductfield', [
                                'product_id' => $id,
                                'field' => 'image',
                                'link_product' => true,
                                'image_ratio' => '1/1',
                                'image_fit' => 'contain',
                                'image_height' => '72px',
                                'image_loading' => 'lazy',
                            ]),
                        ], ['width' => 'auto']),
                        $this->column([
                            $this->node('text', ['content' => $product['category_title'], 'text_style' => 'meta']),
                            $this->node('rmproductfield', [
                                'product_id' => $id,
                                'field' => 'title',
                                'link_product' => true,
                                'title_element' => 'h3',
                                'title_style' => 'h5',
                                'margin_top' => 'small',
                            ]),
                        ], ['width' => 'expand']),
                    ], ['column_gap' => 'small', 'row_gap' => 'small', 'vertical_align' => 'middle']),
                ]),
                $this->tableCell('', 'Артикул', ['wrap_mode' => 'nowrap'], [
                    $this->node('rmproductfield', ['product_id' => $id, 'field' => 'code', 'text_style' => 'meta']),
                ]),
                $this->tableCell('', 'Цена', ['wrap_mode' => 'nowrap'], [
                    $this->node('rmproductfield', [
                        'product_id' => $id,
                        'field' => 'price',
                        'text_style' => 'lead',
                        'show_base_price' => true,
                        // The compact price cell keeps the crossed-out base
                        // price, but omits the separate discount badge. The
                        // badge would force a horizontal overflow in the
                        // 320–390px mobile card layout.
                        'show_discount' => false,
                    ]),
                ]),
                $this->tableCell('', 'Наличие', ['wrap_mode' => 'nowrap'], [
                    $this->node('rmproductfield', ['product_id' => $id, 'field' => 'availability', 'text_style' => 'small']),
                ]),
                $this->tableCell('', 'Действие', [
                    'mobile_behavior' => 'full',
                    'mobile_label_position' => 'hidden',
                    'mobile_order' => 'last',
                ], [
                    $this->node('rmbuy', [
                        'product_id' => $id,
                        'label' => 'В корзину',
                        'button_style' => 'primary',
                        'button_size' => 'small',
                        'show_count' => false,
                        'fullwidth' => true,
                    ]),
                    $this->node('rmquickview', [
                        'product_id' => $id,
                        'label' => 'Быстрый просмотр',
                        'button_style' => 'text',
                        'button_size' => 'small',
                        'modal_size' => 'container',
                        'fullwidth' => true,
                        'margin_top' => 'small',
                    ]),
                ]),
            ]);
        }

        return [$this->node('rmtable', [
            'caption' => 'Тестовый прайс-каталог',
            'caption_visibility' => 'screen-reader',
            'table_style' => 'divider',
            'table_size' => 'small',
            'table_hover' => true,
            'table_vertical_align' => 'middle',
            'container_style' => 'default',
            'container_size' => 'small',
            'container_border' => true,
            'container_radius' => true,
            'container_shadow' => 'small',
            'responsive_mode' => 'cards',
            'responsive_breakpoint' => 'm',
            'mobile_label_position' => 'left',
            'mobile_card_style' => 'default',
            'mobile_card_gap' => 'small',
            'mobile_card_padding' => 'small',
            'sticky_header' => true,
            'sticky_first' => false,
        ], $rows)];
