    private function productCard(int $id, string $category, string $mode): array
    {
        $main = $this->node('rmproductcard_main', [], [
            $this->node('rmproductfield', [
                'product_id' => $id,
                'field' => 'image',
                'link_product' => true,
                'image_ratio' => '4/3',
                'image_fit' => 'contain',
                'image_loading' => 'lazy',
            ]),
            $this->node('text', ['content' => $category, 'text_style' => 'meta', 'margin_top' => 'small']),
            $this->node('rmproductfield', [
                'product_id' => $id,
                'field' => 'title',
                'link_product' => true,
                'title_element' => 'h3',
                'title_style' => 'h4',
                'margin_top' => 'small',
            ]),
            $this->node('rmproductfield', [
                'product_id' => $id,
                'field' => 'price',
                'text_style' => 'large',
                'show_base_price' => true,
                'show_discount' => true,
                'margin_top' => 'small',
            ]),
            $this->node('rmproductfield', [
                'product_id' => $id,
                'field' => 'availability',
                'margin_top' => 'small',
            ]),
        ]);

        $dropdown = $this->node('rmproductcard_dropdown', [
            'display_mode' => $mode === 'tile' ? 'hover' : 'default',
            'hover_breakpoint' => 'm',
            'panel_style' => 'default',
            'panel_padding' => 'small',
            'show_divider' => false,
            'max_height' => 680,
        ], [
            $this->variants($id, 'buttons'),
            $this->node('rmbuy', [
                'product_id' => $id,
                'label' => 'В корзину',
                'button_style' => 'primary',
                'button_size' => 'small',
                'show_count' => false,
                'fullwidth' => true,
                'margin_top' => 'small',
            ]),
            $this->node('rmquickview', [
                'product_id' => $id,
                'label' => 'Быстрый просмотр',
                'button_style' => 'text',
                'button_size' => 'small',
                'modal_size' => 'container',
                'fullwidth' => true,
                'margin_top' => 'small',
            ]),
        ]);

        return $this->node('rmproductcard', ['product_id' => $id], [$main, $dropdown]);
    }

    private function variants(int $id, string $style): array
    {
        return $this->node('rmvariantselector', [
            'product_id' => $id,
            'variant_fields' => ['catalog-color', 'catalog-size', 'catalog-edition'],
            'style' => $style,
            'action' => 'ajax',
            'button_style' => 'default',
            'image_fit' => 'contain',
            'show_labels' => true,
            'show_selected_value' => true,
            'disable_unavailable' => true,
            'update_url' => 'none',
            'margin_top' => 'small',
        ]);
    }

    private function modeNavigation(): array
    {
        return $this->node('button', ['margin_bottom' => 'large'], [
            $this->node('button_item', ['content' => 'Обзор', 'link' => '/index.php/ytdynamics-catalog-layouts', 'button_style' => 'text']),
            $this->node('button_item', ['content' => 'Плитка', 'link' => '/index.php/ytdynamics-catalog-tile', 'button_style' => 'default']),
            $this->node('button_item', ['content' => 'Компактно', 'link' => '/index.php/ytdynamics-catalog-compact', 'button_style' => 'default']),
            $this->node('button_item', ['content' => 'Строки', 'link' => '/index.php/ytdynamics-catalog-list', 'button_style' => 'default']),
            $this->node('button_item', ['content' => 'Прайс', 'link' => '/index.php/ytdynamics-catalog-price', 'button_style' => 'default']),
        ]);
    }

    private function hero(string $title, string $description): array
    {
        return $this->section('', [
            $this->node('text', ['content' => 'YTDYNAMICS · CATALOG COMPOSITION', 'text_style' => 'meta']),
            $this->node('headline', [
                'content' => $title,
                'title_element' => 'h1',
                'title_style' => 'heading-small',
                'margin_top' => 'small',
            ]),
            $this->node('text', ['content' => $description, 'text_style' => 'lead', 'margin_top' => 'small']),
        ], 'default', 'small');
    }

    private function section(
        string $title,
        array $children,
        string $style = 'default',
        string $padding = 'default'
    ): array {
        if ($title !== '') {
            array_unshift($children, $this->node('headline', [
                'content' => $title,
                'title_element' => 'h2',
                'title_style' => 'h2',
                'margin_bottom' => 'medium',
            ]));
        }

        return $this->node('section', ['style' => $style, 'padding' => $padding, 'width' => 'default'], [
            $this->row([$this->column($children, ['width_medium' => '1-1'])]),
        ]);
    }

    private function layout(array $sections): array
    {
        return ['type' => 'layout', 'children' => $sections, 'version' => '5.0.42'];
    }

    private function row(array $columns, array $props = []): array
    {
        return $this->node('row', $props, $columns);
    }

    private function column(array $children, array $props = []): array
    {
        return $this->node('column', $props, $children);
    }

    private function button(string $content, string $link, string $style = 'default'): array
    {
        return $this->node('button', ['margin_top' => 'small'], [
            $this->node('button_item', ['content' => $content, 'link' => $link, 'button_style' => $style]),
        ]);
    }

    private function tableCell(
        string $text,
        string $mobileLabel,
        array $props = [],
        array $children = []
    ): array {
        return $this->node('rmtable_cell', array_merge([
            'text' => $text,
            'mobile_label' => $mobileLabel,
            'cell_type' => 'auto',
            'scope' => 'auto',
            'mobile_behavior' => 'show',
        ], $props), $children);
    }

    private function node(string $type, array $props = [], array $children = []): array
    {
        $node = ['type' => $type];
        if ($props !== []) {
            $node['props'] = $props;
        }
        if ($children !== []) {
            $node['children'] = $children;
        }

        return $node;
    }

    private function upsertArticle(string $alias, string $title, array $layout): int
    {
        $id = (int) ($this->value('SELECT id FROM joom_content WHERE alias = ?', [$alias]) ?: 0);
        $data = [
            'title' => $title,
            'alias' => $alias,
            'introtext' => '<p>Generated YTDynamics catalogue composition demo.</p>',
            'fulltext' => '<!-- ' . $this->json($layout) . ' -->',
            'state' => 1,
            'catid' => self::ARTICLE_CATEGORY_ID,
            'modified' => $this->now,
            'modified_by' => self::CREATED_BY,
            'images' => '{}',
            'urls' => '{}',
            'attribs' => '{}',
            'metakey' => '',
            'metadesc' => 'YTDynamics Builder catalogue mode demo',
            'access' => 1,
            'metadata' => '{}',
            'featured' => 0,
            'language' => '*',
            'note' => 'Generated by tools/seed-catalog-mode-demos.php',
        ];
        if ($id > 0) {
            $this->update('joom_content', $data, 'id = ?', [$id]);
            return $id;
        }

        $data += [
            'asset_id' => 0,
            'created' => $this->now,
            'created_by' => self::CREATED_BY,
            'created_by_alias' => '',
            'checked_out' => null,
            'checked_out_time' => null,
            'publish_up' => $this->now,
            'publish_down' => null,
            'version' => 1,
            'ordering' => 0,
            'hits' => 0,
        ];

        return $this->insert('joom_content', $data);
    }

    private function upsertMenu(string $alias, string $title, int $articleId): void
    {
        $id = (int) ($this->value('SELECT id FROM joom_menu WHERE alias = ?', [$alias]) ?: 0);
        $componentId = (int) $this->value(
            "SELECT extension_id FROM joom_extensions WHERE element = 'com_content' AND type = 'component'"
        );
        $data = [
            'menutype' => 'mainmenu',
            'title' => $title,
            'alias' => $alias,
            'note' => 'Generated catalogue mode demo',
            'path' => $alias,
            'link' => 'index.php?option=com_content&view=article&id=' . $articleId,
            'type' => 'component',
            'published' => 1,
            'parent_id' => 1,
            'level' => 1,
            'component_id' => $componentId,
            'checked_out' => null,
            'checked_out_time' => null,
            'browserNav' => 0,
            'access' => 1,
            'img' => '',
            'template_style_id' => 0,
            'params' => '{}',
            'home' => 0,
            'language' => '*',
            'client_id' => 0,
            'publish_up' => null,
            'publish_down' => null,
        ];
        if ($id > 0) {
            $this->update('joom_menu', $data, 'id = ?', [$id]);
            return;
        }

        $right = (int) $this->value("SELECT COALESCE(MAX(rgt), 1) FROM joom_menu WHERE menutype = 'mainmenu'");
        $data['lft'] = $right + 1;
        $data['rgt'] = $right + 2;
        $this->insert('joom_menu', $data);
    }

    private function json(mixed $value): string
    {
        return json_encode($value, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR);
    }

    private function query(string $sql, array $params = []): PDOStatement
    {
        $statement = $this->db->prepare($sql);
        $statement->execute(array_values($params));
        return $statement;
    }

    private function value(string $sql, array $params = []): mixed
    {
        return $this->query($sql, $params)->fetchColumn();
    }

    private function insert(string $table, array $data): int
    {
        $columns = array_keys($data);
        $marks = implode(',', array_fill(0, count($columns), '?'));
        $sql = sprintf('INSERT INTO %s (`%s`) VALUES (%s)', $table, implode('`,`', $columns), $marks);
        $this->query($sql, array_values($data));
        return (int) $this->db->lastInsertId();
    }

    private function update(string $table, array $data, string $where, array $whereParams = []): void
    {
        $assignments = implode(', ', array_map(
            static fn(string $column): string => "`{$column}` = ?",
            array_keys($data)
        ));
        $this->query(
            "UPDATE {$table} SET {$assignments} WHERE {$where}",
            array_merge(array_values($data), $whereParams)
        );
    }
}

(new CatalogModeDemoSeeder())->run();
